python3 - <<'PY'
import json, os, glob
B='/home/comdare/Projekte/Research/probst-diplomarbeit-cache-engine/docs/sessions/backups/20260806-workflow-rohdaten/journals'
OUT='/home/comdare/.claude/jobs/5a19728e/tmp/ALLE-ERGEBNISSE'
os.makedirs(OUT, exist_ok=True)
items=[]
for f in sorted(glob.glob(B+'/*.jsonl')):
    wf=os.path.basename(f).replace('.journal.jsonl','')
    meta={}
    for line in open(f, errors='replace'):
        try: o=json.loads(line)
        except Exception: continue
        t=o.get('type')
        if t in ('start','workflow_start','meta'):
            meta=o
        if t=='result':
            r=o.get('result')
            txt=r if isinstance(r,str) else json.dumps(r, ensure_ascii=False, indent=1)
            items.append({'wf':wf,'label':o.get('label') or o.get('agentId','?'),
                          'phase':o.get('phase',''), 'txt':txt,
                          'desc':(meta.get('description') or meta.get('name') or '')})
# nach Groesse sortieren: die substanziellsten zuerst
items.sort(key=lambda i:-len(i['txt']))
# Portionen zu je ~180 KB
part=[]; cur=[]; size=0
for it in items:
    cur.append(it); size+=len(it['txt'])
    if size>180000:
        part.append(cur); cur=[]; size=0
if cur: part.append(cur)
for n,p in enumerate(part,1):
    with open('%s/teil-%02d.md'%(OUT,n),'w') as fh:
        for it in p:
            fh.write("\n\n" + "="*90 + "\n")
            fh.write("## [%s] %s  (Phase: %s)\n" % (it['wf'], it['label'], it['phase'] or '-'))
            if it['desc']: fh.write("Welle: %s\n" % it['desc'][:200])
            fh.write("="*90 + "\n\n")
            fh.write(it['txt'])
print("Teile: %d" % len(part))
for n,p in enumerate(part,1):
    print("  teil-%02d.md  %d Berichte  %d KB" % (n, len(p), sum(len(i['txt']) for i in p)//1024))
PY

